contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        (uint256 v1, uint256 t1, Fixed18 p1) = _readCurrentVersion();
        (uint256 v2, uint256 t2, Fixed18 p2) = _readOracleCurrentVersion();
        (int256 ptype, int256 pdirection, bytes30 pdata) = _readPayoffDefinition();

        assert(
            v1 == v2 &&
            t1 == t2 &&
            Fixed18.unwrap(p1) == _transform(ptype, pdirection, pdata, p2)
        );
    }

    function _readCurrentVersion() private view returns (uint256, uint256, Fixed18) {
        IOracleProvider.OracleVersion memory ov = c.currentVersion();
        return (ov.version, ov.timestamp, ov.price);
    }

    function _readOracleCurrentVersion() private view returns (uint256, uint256, Fixed18) {
        IOracleProvider.OracleVersion memory ov = c.oracle().currentVersion();
        return (ov.version, ov.timestamp, ov.price);
    }

    function _readPayoffDefinition() private view returns (int256, int256, bytes30) {
        PayoffDefinition memory pd = c.payoffDefinition();
        return (int256(pd.payoffType), int256(pd.payoffDirection), pd.data);
    }

    function _transform(int256 ptype, int256 pdirection, bytes30 pdata, Fixed18 price) private pure returns (int256) {
        ptype;
        pdirection;
        pdata;
        return Fixed18.unwrap(price);
    }

    receive() external payable {}
}

