            positionFee: positionFee_,
            makerLimit: makerLimit_,
            utilizationCurve: utilizationCurve_
        });

        bool initializeReverted;
        try c.initialize(info) {
            initializeReverted = false;
        } catch {
            initializeReverted = true;
        }

        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        address observedController = address(c.controller());

        assert(
            (initializeReverted || !settleReverted)
                ? (observedController == address(this))
                : (observedController == address(this))
        );
    }

    receive() external payable {}
