contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account) public payable {
        require(true);

        // Read the account's current observable position before deciding call.
        uint256 accountVersionBefore = c.latestVersion(account);
        uint256 globalVersionBefore = c.latestVersion();

        // Read pre-position and public position getters (read-only calls).
        ( , , ) = c.pre(account);
        (uint256 maker, uint256 taker) = c.position(account);

        // Read the maintenance value returned by the public call.
        uint256 m = c.maintenance(account);

        // Read through position getter again to confirm nothing changed except return value.
        (uint256 makerAfter, uint256 takerAfter) = c.position(account);
        uint256 accountVersionAfter = c.latestVersion(account);
        uint256 globalVersionAfter = c.latestVersion();

        // General rule: maintenance(account) is deterministic function of position itself.
        // The same observable position state must yield the same maintenance value.
        assert(
            maker == makerAfter &&
            taker == takerAfter &&
            accountVersionBefore == accountVersionAfter &&
            globalVersionBefore == globalVersionAfter
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account) public payable {
        require(true);

        // Read the account's current observable position before the deciding call.
        uint256 accountVersionBefore = c.latestVersion(account);
        uint256 globalVersionBefore = c.latestVersion();
        PrePosition memory preBefore = c.pre(account);
        Position memory posBefore = c.position(account);

        // Deciding call: the public maintenance getter.
        uint256 m = c.maintenance(account);

        // Read the same observable state again after the call.
        uint256 accountVersionAfter = c.latestVersion(account);
        uint256 globalVersionAfter = c.latestVersion();
        PrePosition memory preAfter = c.pre(account);
        Position memory posAfter = c.position(account);

        // General rule: maintenance is a pure view over the account's observable
        // position state; it must leave that state unchanged and be deterministic.
        assert(
            m == c.maintenance(account) &&
            accountVersionBefore == accountVersionAfter &&
            globalVersionBefore == globalVersionAfter &&
            preBefore.oracleVersion == preAfter.oracleVersion &&
            posBefore.maker == posAfter.maker &&
            posBefore.taker == posAfter.taker
        );
    }

    receive() external payable {}
}

